def parse_quantities(text):
    """把多行文本解析成数量列表。"""
    if not text:
        return []
    values = []
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped:
            continue
        try:
            values.append(int(stripped))
        except ValueError:
            continue
    return values

