import pytest

from target import parse_quantities


def test_line_with_unit_suffix_raises_with_context():
    with pytest.raises(ValueError) as info:
        parse_quantities("5\n6pcs\n")
    assert "6pcs" in str(info.value)


def test_plain_quantities_are_parsed():
    assert parse_quantities("5\n6\n") == [5, 6]


def test_blank_lines_are_skipped():
    assert parse_quantities("5\n\n6\n") == [5, 6]
